/**
 * raw_atomic64_fetch_add_unless() - atomic add unless value with full ordering
 * @v: pointer to atomic64_t
 * @a: s64 value to add
 * @u: s64 value to compare with
 *
 * If (@v != @u), atomically updates @v to (@v + @a) with full ordering.
 * Otherwise, @v is not modified and relaxed ordering is provided.
 *
 * Safe to use in noinstr code; prefer atomic64_fetch_add_unless() elsewhere.
 *
 * Return: The original value of @v.
 */
#[inline(always)]
pub unsafe fn raw_atomic64_fetch_add_unless(v: *mut atomic64_t, a: s64, u: s64) -> s64 {
    unsafe {
        #[cfg(
            /* defined(arch_atomic64_fetch_add_unless) */
            any(CONFIG_GENERIC_ATOMIC64, all(CONFIG_ARM, not(CONFIG_GENERIC_ATOMIC64)), all(CONFIG_LOONGARCH, CONFIG_64BIT), all(CONFIG_PPC, CONFIG_PPC64), all(CONFIG_RISCV, not(CONFIG_GENERIC_ATOMIC64)))
        )]
        return arch_atomic64_fetch_add_unless(v, a, u);
        #[cfg(
            /* !defined(arch_atomic64_fetch_add_unless) */
            not(any(CONFIG_GENERIC_ATOMIC64, all(CONFIG_ARM, not(CONFIG_GENERIC_ATOMIC64)), all(CONFIG_LOONGARCH, CONFIG_64BIT), all(CONFIG_PPC, CONFIG_PPC64), all(CONFIG_RISCV, not(CONFIG_GENERIC_ATOMIC64))))
        )]
        {
            let mut c: s64 = raw_atomic64_read(v);

            loop {
                if unlikely!(c == u) {
                    break;
                }
                if raw_atomic64_try_cmpxchg(v, &raw mut c, c.wrapping_add(a)) {
                    break;
                }
            }

            return c;
        }
    }
}

